import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 7
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    ))
    if not records:
        return {"columns": [], "rows": []}

    def populated_fields(record):
        return sum(bool(value.strip()) for value in record)

    header_index = next(
        (
            index
            for index, record in enumerate(records)
            if len(record) == expected_width
            and populated_fields(record) == expected_width
        ),
        None,
    )
    if header_index is None:
        header_index = next(
            (index for index, record in enumerate(records)
             if populated_fields(record) > 1),
            None,
        )
    if header_index is None:
        return {"columns": [], "rows": records}

    columns = records[header_index][:]
    rows = records[header_index + 1:]

    # Ignore empty overflow for sizing, but keep any populated overflow fields.
    width = max(expected_width, len(columns))
    for row in rows:
        end = len(row)
        while end > width and row[end - 1] == "":
            end -= 1
        width = max(width, end)

    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        name = f"column_{position}"
        while name in used_names:
            name += "_"
        columns.append(name)
        used_names.add(name)

    return {
        "columns": columns,
        "rows": [row[:width] + [""] * max(0, width - len(row)) for row in rows],
    }
